#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_engine_path2.py
# ─────────────────────────────────────────────────────────────
# ЕДИНЫЙ ДВИЖОК · ПУТЬ 2 — источник с двумя кранами, вся лесенка ТФ.
#
# Кладёт НОВЫЕ файлы в studio/modules/trading/:
#   feed_source.py  — источник баров (два крана: терминал | папка)
#   engine.py       — мотор-дирижёр
#   council.py      — чистая будилка Совета
#   probe_engine.py — верстак
# И хирургически правит ТРИ живых файла (через якоря, с бэкапом):
#   mt5_feed.py     — pull_bars спрашивает источник (не прямой терминал)
#   iskra_live.py   — рабочий бар через источник (обе двери Искры)
#   ui_exchange.py  — кнопки режима пишут включённый кран на площадь
#
# Все правки С ОТКАТОМ: источник упал → старое поведение (терминал).
# Идемпотентно: маркер ENGINE_ONE_DOOR_V1, бэкап .bak. Повторный запуск
# не дублирует правки (видит маркер). Запуск из КОРНЯ репы:
#   python patch_engine_path2.py
#
# ОТКАТ: каждый тронутый файл имеет .bak_ДАТА рядом. Восстановить —
# переименовать .bak обратно. Новые файлы просто удалить.
#
# Проверка после установки (тестер, вся лесенка, MT5 молчит):
#   1) в кабинете переключи тумблер на ТЕСТЕР, выбери золото
#   2) жми РЫНОК — Искра спускается по этажам из папки, без MT5
# Или верстаком напрямую:
#   python -m studio.modules.trading.probe_engine \\
#          studio/modules/trading/test_data/XAUUSDH4.csv XAUUSD H4 --signals 1
# ─────────────────────────────────────────────────────────────
import sys, py_compile, shutil, base64
from datetime import datetime
from pathlib import Path

MARKER = "ENGINE_ONE_DOOR_V1"
ROOT = Path(".")
TRADING = Path("studio/modules/trading")
ECONOMY = Path("studio/economy")

NEW_FILES = {
    "studio/modules/trading/feed_source.py":  "",
    "studio/modules/trading/engine.py":       "",
    "studio/modules/trading/council.py":      "",
    "studio/modules/trading/probe_engine.py": "",
}

EDITS = [
    ("studio/modules/trading/iskra_live.py",  '    from studio.modules.trading.mt5_feed import _terminal, _fetch\n    mt5 = _terminal()\n    if mt5 is None:\n        return {"ok": False, "error": "MetaTrader5 не установлен в Python",\n                "narrative": "", "signal": {}, "stats": _load_stats(), "market": {}}\n\n    bars, point = _fetch(mt5, symbol, timeframe, bars_count)', '    # ENGINE_ONE_DOOR_V1: рабочий бар через ИСТОЧНИК (кран real|tester),\n    # не через прямой терминал. В тестовом режиме берётся из папки —\n    # MT5 не поднимается. Реал-кран идёт в терминал как прежде.\n    from studio.modules.trading.mt5_feed import pull_bars\n    bars, point = pull_bars(symbol, timeframe, bars_count)'),
    ("studio/modules/trading/mt5_feed.py",    '    mt5 = _terminal()\n    if mt5 is None:\n        print("[FEED] ℹ️  MetaTrader5 не установлен — pull_bars простаивает")\n        return [], None\n    return _fetch(mt5, symbol, timeframe, count)', '    # ENGINE_ONE_DOOR_V1: дверь спрашивает ИСТОЧНИК (feed_source),\n    # а не лезет в терминал напрямую. Источник смотрит включённый кран\n    # (real|tester) и идёт в терминал ИЛИ в папку test_data. Так спуск\n    # Искры в тестовом режиме НЕ поднимает MT5 — берёт этажи из CSV.\n    try:\n        from studio.modules.trading.feed_source import bars as _source_bars\n        return _source_bars(symbol, timeframe, count)\n    except Exception as _e:\n        print(f"[FEED] ℹ️  источник недоступен ({_e}) — прямой терминал")\n        mt5 = _terminal()\n        if mt5 is None:\n            print("[FEED] ℹ️  MetaTrader5 не установлен — pull_bars простаивает")\n            return [], None\n        return _fetch(mt5, symbol, timeframe, count)'),
    ("studio/economy/ui_exchange.py",         '        state["mode"] = mode\n        is_tester = (mode == "tester")', '        state["mode"] = mode\n        # ENGINE_ONE_DOOR_V1: кнопка пишет включённый кран на площадь\n        # (trading_state["feed"]). Источник прочитает и направит бар:\n        # tester → папка test_data, real → терминал. Один движок, два крана.\n        try:\n            from studio.modules.trading.feed_source import set_feed_mode\n            _sym = None\n            _assets = state.get("loaded_assets", [])\n            _ai = state.get("active_asset")\n            if _assets and _ai is not None and 0 <= _ai < len(_assets):\n                _sym = _assets[_ai].get("symbol")\n            set_feed_mode(mode, _sym)\n        except Exception as _e:\n            print(f"[EXCHANGE] feed_source не подключён: {_e}")\n        is_tester = (mode == "tester")'),
]

def _backup(path):
    bak = path.with_suffix(path.suffix + f".bak_{datetime.now():%Y%m%d_%H%M%S}")
    shutil.copy2(path, bak)
    return bak

def _write_new(rel, b64):
    path = ROOT / rel
    code = base64.b64decode(b64).decode("utf-8")
    if not path.parent.exists():
        print(f"  ❌ нет папки {path.parent}"); return False
    if path.exists():
        bak = _backup(path)
        print(f"  ↻ {path.name}: есть — бэкап {bak.name}")
    path.write_text(code, encoding="utf-8")
    py_compile.compile(str(path), doraise=True)
    print(f"  ✓ {path.name}: записан")
    return True

def _edit(rel, old, new):
    path = ROOT / rel
    if not path.exists():
        print(f"  ❌ {rel}: файла нет — пропуск"); return False
    text = path.read_text(encoding="utf-8")
    if MARKER in text and new.strip() in text:
        print(f"  = {path.name}: правка уже стоит (маркер) — пропуск")
        return True
    if old not in text:
        print(f"  ⚠ {path.name}: якорь не найден — НЕ тронут (проверь вручную)")
        return False
    bak = _backup(path)
    text = text.replace(old, new, 1)
    path.write_text(text, encoding="utf-8")
    try:
        py_compile.compile(str(path), doraise=True)
    except py_compile.PyCompileError as e:
        shutil.copy2(bak, path)  # откат правки если сломали синтаксис
        print(f"  ❌ {path.name}: правка сломала синтаксис — ОТКАЧЕНО ({e})")
        return False
    print(f"  ✓ {path.name}: правка легла (бэкап {bak.name})")
    return True

def main():
    if not TRADING.exists():
        print(f"❌ Нет {TRADING} — запусти из КОРНЯ репы"); sys.exit(1)
    print("─"*64)
    print("  ЕДИНЫЙ ДВИЖОК · ПУТЬ 2 · источник с двумя кранами")
    print("─"*64)
    print("  Новые файлы:")
    ok = True
    for rel, b64 in NEW_FILES.items():
        ok &= _write_new(rel, b64)
    print("  Правки живых файлов (с откатом):")
    for rel, old, new in EDITS:
        ok &= _edit(rel, old, new)
    print("─"*64)
    if ok:
        print("  ✅ Путь 2 встал. Тумблер ТЕСТЕР → бар из папки, MT5 молчит.")
    else:
        print("  ⚠ Часть шагов не прошла — смотри пометки выше. Бэкапы рядом (.bak).")
    print("─"*64)

if __name__ == "__main__":
    main()
